        public static UnitConverterPowerDensityUnit[] GetUnitsForSystem(UnitConverterUnitSystem system)
        {
            var units = new List<UnitConverterPowerDensityUnit>();
            for (int i = 0; i < 49; i++) if (GetUnitSystem((UnitConverterPowerDensityUnit)i) == system) units.Add((UnitConverterPowerDensityUnit)i);
            return units.ToArray();
        }

        public static IReadOnlyList<UnitConverterUnitInfo> GetUnits() { return Metadata.Units; }
        public static UnitConverterUnitInfo GetUnitInfo(UnitConverterPowerDensityUnit unit) { Validate(unit); return Metadata.Units[(int)unit]; }
        public static string GetSymbol(UnitConverterPowerDensityUnit unit, IFormatProvider provider) { return GetUnitInfo(unit).GetSymbol(provider); }

        public static bool TryParseUnit(string text, out UnitConverterPowerDensityUnit unit, IFormatProvider provider = null)
        {
            int id; bool success = UnitConverterText.TryUnit(text, GetUnits(), provider, out id);
            unit = success ? (UnitConverterPowerDensityUnit)id : default(UnitConverterPowerDensityUnit); return success;
        }

        public static UnitConverterPowerDensityUnit ParseUnit(string text, IFormatProvider provider = null)
        {
            UnitConverterPowerDensityUnit unit;
            if (!TryParseUnit(text, out unit, provider)) throw new FormatException("Unknown or ambiguous PowerDensity unit: " + text);
            return unit;
        }

        public static bool TryParse(string text, out UnitConverterPowerDensityValue quantity, IFormatProvider provider = null)
        {
            double value; int id;
            bool success = UnitConverterText.TryValue(text, GetUnits(), provider, out value, out id);
            quantity = success ? new UnitConverterPowerDensityValue(value, (UnitConverterPowerDensityUnit)id) : default(UnitConverterPowerDensityValue); return success;
        }

        public static UnitConverterPowerDensityValue Parse(string text, IFormatProvider provider = null)
        {
            UnitConverterPowerDensityValue quantity;
            if (!TryParse(text, out quantity, provider)) throw new FormatException("Expected a finite number and an unambiguous PowerDensity unit.");
            return quantity;
        }

        public static string Format(double value, UnitConverterPowerDensityUnit unit, string format = "G", IFormatProvider provider = null)
        {
            return value.ToString(format, provider ?? CultureInfo.CurrentCulture) + " " + GetSymbol(unit, provider);
        }


